class Keeper
  private _o: Object?;

  public method Keep(s: IReadOnlySpan<int>)
    var id: (IReadOnlySpan<int>) -> IReadOnlySpan<int> := lambda(x) => x;  // capture-free; param-sourced return
    var up: (IReadOnlySpan<int>) -> Object := id;  // §27.1.1: interface return slot is covariant; no span conversion
    _o := up(s);   // row-4 result: Object borrow sourced at plain param s -> field-store residual admits
  end Keep;
end Keeper;

// caller
var xs: Array<int> := [1, 2, 3];
var k := new Keeper();
k.Keep(xs.AsSpan());   // the span (read as such at the parameter) now lives boxed in k._o
xs.Dispose();          // site-announced; k outlives xs
// a later (k._o as IReadOnlySpan<int>)![0] faults in checked mode (0153), but §9.7 says
// a span is stored past its bound at no position, rejected statically.
// Twin: Put(xs: IReadOnlyList<IReadOnlySpan<int>>) { var v: IReadOnlyList<Object> := xs; _o := v[0]; }

class Summer
  public static async method Sum(xs: Array<int>): Task<int>
    var s: IReadOnlySpan<int> := xs.AsSpan();   // caller-sourced (plain parameter xs)
    await Task.Delay(10);
    return s[0];                                // s live across the suspension
  end Sum;

  public static async method Head(s: IReadOnlySpan<int>): Task<int>
    await Task.Delay(10);                       // parameter of declared interface type
    return s[0];
  end Head;
end Summer;
// Reading 1 (holds-borrows row, §9.7 posture): read as the span it boxes ->
//   Sum rejected at the await; Head rejected at its declaration (as `s: ArraySpan<int>` is).
// Reading 2 (§30.1's literal 'value type that holds borrows'): an interface-typed
//   local/parameter -> admitted under the settlement clause, a stale read faulting.

class Gen
  public static method Pairs(xs: Array<int>): IEnumerable<int>
    var s: IReadOnlySpan<int> := xs.AsSpan();   // source: plain parameter xs (not frame-owned)
    yield return s[0];
    yield return s[1];                          // s live across the first yield
  end Pairs;
end Gen;
// With `var s := xs.AsSpan();` (an ArraySpan<int> local) this is rejected at the first
// yield (§29.4 / §30.1 frame-resident rule). Declared IReadOnlySpan<int>:
// Reading 1 (holds-borrows row: read as the span it boxes) -> rejected likewise.
// Reading 2 (§30.1/§29.4 name only value types) -> an interface-typed local, admitted.
